-- Create "auth_group" table
CREATE TABLE "auth_group" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "name" character varying(150) NOT NULL, PRIMARY KEY ("id"));
-- Create index "auth_group_name_uniq" to table: "auth_group"
CREATE UNIQUE INDEX "auth_group_name_uniq" ON "auth_group" ("name");
-- Create "django_session" table
CREATE TABLE "django_session" ("session_key" character varying(40) NOT NULL, "session_data" text NOT NULL, "expire_date" timestamptz NOT NULL, PRIMARY KEY ("session_key"));
-- Create index "django_session_expire_date" to table: "django_session"
CREATE INDEX "django_session_expire_date" ON "django_session" ("expire_date");
-- Create "django_site" table
CREATE TABLE "django_site" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "domain" character varying(100) NOT NULL, "name" character varying(50) NOT NULL, PRIMARY KEY ("id"));
-- Create index "django_site_domain_uniq" to table: "django_site"
CREATE UNIQUE INDEX "django_site_domain_uniq" ON "django_site" ("domain");
-- Create "django_content_type" table
CREATE TABLE "django_content_type" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "app_label" character varying(100) NOT NULL, "model" character varying(100) NOT NULL, PRIMARY KEY ("id"));
-- Create index "django_content_type_app_label_model_uniq" to table: "django_content_type"
CREATE UNIQUE INDEX "django_content_type_app_label_model_uniq" ON "django_content_type" ("app_label", "model");
-- Create "auth_permission" table
CREATE TABLE "auth_permission" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "name" character varying(255) NOT NULL, "content_type_id" integer NOT NULL, "codename" character varying(100) NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "auth_permission_content_type_id_fk" FOREIGN KEY ("content_type_id") REFERENCES "django_content_type" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "auth_permission_content_type_id" to table: "auth_permission"
CREATE INDEX "auth_permission_content_type_id" ON "auth_permission" ("content_type_id");
-- Create index "auth_permission_content_type_id_codename_uniq" to table: "auth_permission"
CREATE UNIQUE INDEX "auth_permission_content_type_id_codename_uniq" ON "auth_permission" ("content_type_id", "codename");
-- Create "auth_group_permissions" table
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "group_id" integer NOT NULL, "permission_id" integer NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "auth_group_permissions_group_id_fk" FOREIGN KEY ("group_id") REFERENCES "auth_group" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "auth_group_permissions_permission_id_fk" FOREIGN KEY ("permission_id") REFERENCES "auth_permission" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "auth_group_permissions_group_id" to table: "auth_group_permissions"
CREATE INDEX "auth_group_permissions_group_id" ON "auth_group_permissions" ("group_id");
-- Create index "auth_group_permissions_group_id_permission_id_uniq" to table: "auth_group_permissions"
CREATE UNIQUE INDEX "auth_group_permissions_group_id_permission_id_uniq" ON "auth_group_permissions" ("group_id", "permission_id");
-- Create index "auth_group_permissions_permission_id" to table: "auth_group_permissions"
CREATE INDEX "auth_group_permissions_permission_id" ON "auth_group_permissions" ("permission_id");
-- Create "auth_user" table
CREATE TABLE "auth_user" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "password" character varying(128) NOT NULL, "last_login" timestamptz NULL, "is_superuser" boolean NOT NULL, "username" character varying(150) NOT NULL, "first_name" character varying(150) NOT NULL, "last_name" character varying(150) NOT NULL, "email" character varying(254) NOT NULL, "is_staff" boolean NOT NULL, "is_active" boolean NOT NULL, "date_joined" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "auth_user_username_uniq" to table: "auth_user"
CREATE UNIQUE INDEX "auth_user_username_uniq" ON "auth_user" ("username");
-- Create "auth_user_groups" table
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "user_id" integer NOT NULL, "group_id" integer NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "auth_user_groups_group_id_fk" FOREIGN KEY ("group_id") REFERENCES "auth_group" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "auth_user_groups_user_id_fk" FOREIGN KEY ("user_id") REFERENCES "auth_user" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "auth_user_groups_group_id" to table: "auth_user_groups"
CREATE INDEX "auth_user_groups_group_id" ON "auth_user_groups" ("group_id");
-- Create index "auth_user_groups_user_id" to table: "auth_user_groups"
CREATE INDEX "auth_user_groups_user_id" ON "auth_user_groups" ("user_id");
-- Create index "auth_user_groups_user_id_group_id_uniq" to table: "auth_user_groups"
CREATE UNIQUE INDEX "auth_user_groups_user_id_group_id_uniq" ON "auth_user_groups" ("user_id", "group_id");
-- Create "auth_user_user_permissions" table
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "user_id" integer NOT NULL, "permission_id" integer NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "auth_user_user_permissions_permission_id_fk" FOREIGN KEY ("permission_id") REFERENCES "auth_permission" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "auth_user_user_permissions_user_id_fk" FOREIGN KEY ("user_id") REFERENCES "auth_user" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "auth_user_user_permissions_permission_id" to table: "auth_user_user_permissions"
CREATE INDEX "auth_user_user_permissions_permission_id" ON "auth_user_user_permissions" ("permission_id");
-- Create index "auth_user_user_permissions_user_id" to table: "auth_user_user_permissions"
CREATE INDEX "auth_user_user_permissions_user_id" ON "auth_user_user_permissions" ("user_id");
-- Create index "auth_user_user_permissions_user_id_permission_id_uniq" to table: "auth_user_user_permissions"
CREATE UNIQUE INDEX "auth_user_user_permissions_user_id_permission_id_uniq" ON "auth_user_user_permissions" ("user_id", "permission_id");
-- Create "django_admin_log" table
CREATE TABLE "django_admin_log" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "action_time" timestamptz NOT NULL, "object_id" text NULL, "object_repr" character varying(200) NOT NULL, "action_flag" smallint NOT NULL, "change_message" text NOT NULL, "content_type_id" integer NULL, "user_id" integer NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "django_admin_log_content_type_id_fk" FOREIGN KEY ("content_type_id") REFERENCES "django_content_type" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "django_admin_log_user_id_fk" FOREIGN KEY ("user_id") REFERENCES "auth_user" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "django_admin_log_action_flag_check" CHECK (action_flag >= 0));
-- Create index "django_admin_log_content_type_id" to table: "django_admin_log"
CREATE INDEX "django_admin_log_content_type_id" ON "django_admin_log" ("content_type_id");
-- Create index "django_admin_log_user_id" to table: "django_admin_log"
CREATE INDEX "django_admin_log_user_id" ON "django_admin_log" ("user_id");
